"},{"path":"server.js","mode":420,"text":"// Starts the eval's four sites, each on its own port: PORT_<NAME> when the platform (or `atira eval dev`) sets it,
// else the port in atira-eval.json. Every page needs the run's login for its site (atira-kit.js checks it with the
// platform); the handlers get that login, so each run keeps its own state in the one shared app.
import { createServer } from "node:http"
import { guard } from "./atira-kit.js"
import { customerPortal, view as customerPortalView } from "./sites/customer-portal.js"
import { erp, view as erpView } from "./sites/erp.js"
import { port, raw, siteUrl } from "./sites/html.js"
import { mail, view as mailView } from "./sites/mail.js"
import { tenderPortal, view as tenderPortalView } from "./sites/tender-portal.js"

const sites = {
  "tender-portal": [tenderPortal, tenderPortalView],
  "customer-portal": [customerPortal, customerPortalView],
  erp: [erp, erpView],
  mail: [mail, mailView],
}

for (const [name, [handle, view]] of Object.entries(sites)) {
  const layout = (title, body) => view(title, raw(body), false)
  createServer(async (request, response) => {
    try {
      const login = await guard(request, response, name, { layout })
      if (login) await handle(request, response, login)
    } catch (error) {
      console.error(`${name}: ${request.method} ${request.url}:`, error)
      if (!response.headersSent) response.writeHead(500, { "content-type": "text/plain; charset=utf-8" })
      response.end("Interner Fehler")
    }
  }).listen(port(name), () => console.log(`${name} listening on port ${port(name)}, reached at ${siteUrl(name)}`))
}
"},{"path":"sites/customer-portal.js","mode":420,"text":"// The buyer's customer portal (Lieferantenportal): its document register with the technical specification, each
// revision's requirements and the revision history. The Leistungsverzeichnis on the tender portal names a requirement
// per position; this site says what each requirement is. Nothing here changes, so it keeps no per-run state.
import { informationDocuments, specification, tender } from "../world.js"
import { germanDate, html, page, send } from "./html.js"

const nav = [
  ["/", "Startseite"],
  ["/documents", "Dokumente"],
]
export const view = (title, body, signedIn) =>
  page({ site: `Lieferantenportal · ${tender.buyer.name}`, title, nav, body, accent: "#6a2f4f", signedIn })

const current = () => specification.revisions.find((revision) => revision.status === "gültig")

function documents() {
  return view(
    "Dokumente",
    html`<table><thead><tr><th>Dokumentnummer</th><th>Titel</th><th>Typ</th></tr></thead><tbody>
    ${informationDocuments.map(
      (document) =>
        html`<tr><td>${document.number}</td><td><a href="/documents/${document.id}">${document.title}</a></td><td>Allgemein</td></tr>`,
    )}
    <tr><td>${specification.number}</td><td><a href="/documents/specification">${specification.title}</a></td><td>Technische Spezifikation zu ${tender.reference}</td></tr>
    </tbody></table>`,
  )
}

function specificationPage(revision) {
  return view(
    `${specification.number} · ${specification.title}`,
    html`<p>Revision ${revision.revision} vom ${germanDate(revision.date)} · ${revision.status}</p>
    <table><thead><tr><th>Referenz</th><th>Bohrung</th><th>Hub</th><th>Befestigung</th><th>Zertifizierung</th></tr></thead><tbody>${revision.requirements.map(
      (requirement) =>
        html`<tr><td>${requirement.ref}</td><td>${requirement.bore} mm</td><td>${requirement.stroke} mm</td><td>${requirement.mounting}</td><td>${requirement.certification ?? "keine gefordert"}</td></tr>`,
    )}</tbody></table>
    <h2>Revisionshistorie</h2><table><thead><tr><th>Revision</th><th>Datum</th><th>Status</th><th>Änderungsvermerk</th></tr></thead><tbody>${specification.revisions.map(
      (item) =>
        html`<tr><td><a href="/documents/specification?revision=${item.revision}">Revision ${item.revision}</a></td><td>${germanDate(item.date)}</td><td>${item.status}</td><td>${item.note}</td></tr>`,
    )}</tbody></table><p><a href="/documents">Zurück zu den Dokumenten</a></p>`,
  )
}

export async function customerPortal(request, response) {
  const url = new URL(request.url, "http://customer-portal")
  if (request.method !== "GET")
    return send(response, 405, view("Nicht erlaubt", html`<p><a href="/">Zur Startseite</a></p>`))
  if (url.pathname === "/")
    return send(
      response,
      200,
      view(
        "Willkommen im Lieferantenportal",
        html`<p>${tender.buyer.name} stellt Ihnen hier technische Unterlagen und allgemeine Informationen bereit.</p>
        <p><a href="/documents">Zu den Dokumenten</a></p>`,
      ),
    )
  if (url.pathname === "/documents") return send(response, 200, documents())
  if (url.pathname === "/documents/specification") {
    const wanted = url.searchParams.get("revision")
    const revision = wanted ? specification.revisions.find((item) => item.revision === wanted) : current()
    if (revision) return send(response, 200, specificationPage(revision))
  }
  const document = informationDocuments.find((item) => url.pathname === `/documents/${item.id}`)
  if (document)
    return send(
      response,
      200,
      view(
        `${document.number} · ${document.title}`,
        html`<p>${document.content}</p><p><a href="/documents">Zurück zu den Dokumenten</a></p>`,
      ),
    )
  return send(response, 404, view("Seite nicht gefunden", html`<p><a href="/">Zur Startseite</a></p>`))
}
"},{"path":"sites/erp.js","mode":420,"text":"// The bidder's ERP: the material master with each material's attributes, status, stock, lead times and price scale.
import { bidder, materials } from "../world.js"
import { count, html, money, page, send, siteUrl } from "./html.js"

const nav = () => [
  ["/", "Materialstamm"],
  [`${siteUrl("mail")}/`, "Werkpost"],
]
export const view = (title, body, signedIn) =>
  page({ site: `ERP · ${bidder.name}`, title, nav: nav(), body, accent: "#5b4a2f", signedIn })

export async function erp(request, response) {
  const url = new URL(request.url, "http://erp")
  if (request.method === "GET" && url.pathname === "/") {
    const query = (url.searchParams.get("q") ?? "").toLowerCase()
    const rows = materials.filter((material) => `${material.number} ${material.name}`.toLowerCase().includes(query))
    return send(
      response,
      200,
      view(
        "Materialstamm",
        html`<form method="get" action="/"><label>Katalognummer oder Bezeichnung <input name="q" value="${url.searchParams.get("q") ?? ""}"></label><button type="submit">Suchen</button></form>
        <table><thead><tr><th>Katalognummer</th><th>Bezeichnung</th><th>Status</th></tr></thead><tbody>${rows.map(
          (material) =>
            html`<tr><td><a href="/materials/${material.number}">${material.number}</a></td><td>${material.name}</td><td>${material.status}</td></tr>`,
        )}</tbody></table>`,
      ),
    )
  }
  const number = /^\/materials\/([\w-]+)$/.exec(url.pathname)?.[1]
  const material = materials.find((item) => item.number === number)
  if (request.method === "GET" && material)
    return send(
      response,
      200,
      view(
        `${material.number} · ${material.name}`,
        html`<dl><dt>Status</dt><dd>${material.status}</dd><dt>Bohrung</dt><dd>${material.bore} mm</dd>
        <dt>Hub</dt><dd>${material.stroke} mm</dd><dt>Betriebsdruck</dt><dd>${material.pressure} bar</dd>
        <dt>Befestigung</dt><dd>${material.mounting}</dd><dt>Zertifizierung</dt><dd>${material.certification ?? "keine"}</dd>
        <dt>Bestand</dt><dd>${material.stock} Stk</dd><dt>Lieferzeit ab Lager</dt><dd>${count(material.stockWeeks, "Woche", "Wochen")}</dd>
        <dt>Fertigungszeit</dt><dd>${count(material.productionWeeks, "Woche", "Wochen")}</dd></dl>
        <h2>Preisstaffel (EUR netto je Stück)</h2><table><thead><tr><th>ab Menge</th><th>Preis</th></tr></thead><tbody>${material.prices.map(
          (scale) => html`<tr><td>${scale.from} Stk</td><td>${money(scale.price)}</td></tr>`,
        )}</tbody></table><p><a href="/">Zurück zum Materialstamm</a></p>`,
      ),
    )
  return send(response, 404, view("Material nicht gefunden", html`<p><a href="/">Zum Materialstamm</a></p>`))
}
"},{"path":"sites/html.js","mode":420,"text":"// What the four sites share: escaped HTML, the page layout, request helpers, per-run state and the other sites'
// addresses.
import { readFileSync } from "node:fs"

const manifest = JSON.parse(readFileSync(new URL("../atira-eval.json", import.meta.url), "utf8"))

/** A site's name as the platform writes it in variable names: erp → ERP, tender-portal → TENDER_PORTAL. */
const variable = (name) => name.toUpperCase().replace(/[^A-Z0-9]/g, "_")

/** The port a site listens on: PORT_<NAME>, which the platform and `atira eval dev` set, else the manifest's. */
export function port(name) {
  const site = manifest.sites.find((candidate) => candidate.name === name)
  return Number(process.env[`PORT_${variable(name)}`] ?? site?.port)
}

/** Where the agent's browser reaches a site: ATIRA_SITE_URL_<NAME> (its public URL), else localhost. */
export function siteUrl(name) {
  return (process.env[`ATIRA_SITE_URL_${variable(name)}`] ?? `http://localhost:${port(name)}`).replace(/\/+$/, "")
}

class Raw {
  constructor(text) {
    this.text = text
  }
}
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`)
const render = (value) =>
  value === null || value === undefined || value === false
    ? ""
    : value instanceof Raw
      ? value.text
      : Array.isArray(value)
        ? value.map(render).join("")
        : escapeHtml(value)

/** Text that goes into the page as it is: only for markup this app wrote itself, never for input. */
export const raw = (text) => new Raw(text)

/** HTML with every value escaped, except other html`` results; arrays are joined. */
/** "1 Woche", "3 Wochen": a count and its noun, singular or plural. */
export const count = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`

export const html = (strings, ...values) =>
  new Raw(strings.reduce((text, part, index) => text + render(values[index - 1]) + part))

/** A whole page: the site's name in the header, its navigation (with "Abmelden"), the title and the content. */
export function page({ site, title, nav = [], body, accent = "#24527a", signedIn = true }) {
  return html`<!doctype html><html lang="de"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} – ${site}</title>
<style>
  header form{margin-left:auto}header button{margin:0}
  body{margin:0;font:15px/1.5 system-ui,sans-serif;color:#1d232a;background:#f4f5f7}
  header{background:${accent};color:#fff;padding:12px 24px;display:flex;gap:24px;align-items:center;flex-wrap:wrap}
  header strong{font-size:17px}header a{color:#fff}main{max-width:960px;margin:24px auto;padding:0 16px}
  main{overflow-x:auto}table{border-collapse:collapse;width:100%;background:#fff}th,td{border:1px solid #c8ced5;padding:6px 10px;text-align:left}
  th{background:#e7ebef}label{display:block;margin:14px 0}input,select{font:inherit;padding:5px 8px;min-width:260px}
  button{font:inherit;padding:6px 14px;margin:8px 12px 8px 0;cursor:pointer}
  .notice{background:#fff7d6;border:1px solid #c9b45d;padding:10px 14px}
  [role=alert]{border:2px solid #a40000;background:#fff;padding:10px 14px;white-space:pre-line}
  dl{display:grid;grid-template-columns:220px 1fr;background:#fff;border:1px solid #c8ced5}dt,dd{margin:0;padding:6px 10px;border-bottom:1px solid #e1e5e9}
  dt{color:#4a5560}pre{white-space:pre-wrap;background:#fff;border:1px solid #c8ced5;padding:14px;font:inherit}
</style></head><body><header><strong>${site}</strong>${nav.map(([href, text]) => html`<a href="${href}">${text}</a>`)}${signedIn ? html`<form method="post" action="/logout"><button type="submit">Abmelden</button></form>` : ""}</header>
<main><h1>${title}</h1>${body}</main></body></html>`.text
}

/** A request's body as text, at most 1 MB. */
export async function readBody(request) {
  const chunks = []
  let size = 0
  for await (const chunk of request) {
    size += chunk.length
    if (size > 1024 * 1024) throw new Error("request body too large")
    chunks.push(chunk)
  }
  return Buffer.concat(chunks).toString("utf8")
}

/** A form post's fields. */
export const readForm = async (request) => Object.fromEntries(new URLSearchParams(await readBody(request)))

export function send(response, status, body, type = "text/html; charset=utf-8") {
  response.writeHead(status, { "content-type": type, "cache-control": "no-store" })
  response.end(body)
}

export const sendJson = (response, status, value) =>
  send(response, status, JSON.stringify(value), "application/json; charset=utf-8")

export function redirect(response, location) {
  response.writeHead(303, { location })
  response.end()
}

/**
 * A run's own state, made on first use: the app serves every run of this eval version at once, so whatever a run can
 * change is kept per login (its run or preview id) and dropped when the login expires.
 */
export function perRun(fresh) {
  const states = new Map()
  return (login) => {
    const now = Date.now()
    for (const [id, entry] of states) if (entry.expiresAt < now) states.delete(id)
    const key = `${login.kind}:${login.id}`
    if (!states.has(key)) states.set(key, { expiresAt: login.expiresAt, state: fresh() })
    return states.get(key).state
  }
}

/** A number as the German sites write money: 1.234,56 */
export const money = (value) => value.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })

/** A date (YYYY-MM-DD or ISO time) as 05.10.2026 */
export const germanDate = (value) => new Date(value).toLocaleDateString("de-DE", { timeZone: "UTC" })

/**
 * A German number as typed into a form: "3,5" or "12"; with `money`, exactly two decimals and optional thousands
 * dots ("1.234,56"). undefined when it isn't one.
 */
export function germanNumber(text, isMoney = false) {
  const pattern = isMoney ? /^(?:0|[1-9]\d*|[1-9]\d{0,2}(?:\.\d{3})+),\d{2}$/ : /^(?:0|[1-9]\d*)(?:,\d{1,2})?$/
  if (!pattern.test(text ?? "")) return undefined
  return Number(text.replaceAll(".", "").replace(",", "."))
}
"},{"path":"sites/mail.js","mode":420,"text":"// The bidder's webmail (Werkpost): the inbox with the customer's request and the discount approvals, and the signing
// TANs the tender portal sends. All four sites run in one process, so the tender portal hands a TAN over with a
// function call; each run has its own inbox, so a run only sees its own TANs.
import { bidder, messages } from "../world.js"
import { germanDate, html, page, perRun, send, siteUrl } from "./html.js"

const inboxOf = perRun(() => [...messages])
const nav = () => [
  ["/", "Posteingang"],
  [`${siteUrl("erp")}/`, "ERP"],
]
export const view = (title, body, signedIn) =>
  page({ site: `Werkpost · ${bidder.mailbox}`, title, nav: nav(), body, accent: "#3d5a3f", signedIn })

/** The tender portal sends a signing TAN: a new message in the run's inbox. */
export function deliverTan(login, tan, reference, count) {
  inboxOf(login).push({
    id: `tan-${count}`,
    date: new Date().toISOString(),
    from: "signatur@vergabeportal.example",
    subject: `Ihre Signatur-TAN für ${reference}`,
    body: `Ihre Signatur-TAN für die Angebotsabgabe zu ${reference} lautet: ${tan}\n\nNur die zuletzt angeforderte TAN ist gültig.`,
  })
}

export async function mail(request, response, login) {
  const url = new URL(request.url, "http://mail")
  const inbox = inboxOf(login)
  if (request.method === "GET" && url.pathname === "/") {
    const query = (url.searchParams.get("q") ?? "").toLowerCase()
    const rows = inbox
      .filter((message) => `${message.from} ${message.subject} ${message.body}`.toLowerCase().includes(query))
      .sort((a, b) => b.date.localeCompare(a.date))
    return send(
      response,
      200,
      view(
        "Posteingang",
        html`<form method="get" action="/"><label>Suche <input name="q" value="${url.searchParams.get("q") ?? ""}"></label><button type="submit">Suchen</button></form>
        <table><thead><tr><th>Datum</th><th>Von</th><th>Betreff</th></tr></thead><tbody>${rows.map(
          (message) =>
            html`<tr><td>${germanDate(message.date)}</td><td>${message.from}</td><td><a href="/messages/${message.id}">${message.subject}</a></td></tr>`,
        )}</tbody></table>`,
      ),
    )
  }
  const id = /^\/messages\/([\w-]+)$/.exec(url.pathname)?.[1]
  const message = inbox.find((item) => item.id === id)
  if (request.method === "GET" && message)
    return send(
      response,
      200,
      view(
        message.subject,
        html`<dl><dt>Von</dt><dd>${message.from}</dd><dt>An</dt><dd>${bidder.mailbox}</dd><dt>Datum</dt><dd>${germanDate(message.date)}</dd></dl>
        <pre>${message.body}</pre><p><a href="/">Zurück zum Posteingang</a></p>`,
      ),
    )
  return send(response, 404, view("Nachricht nicht gefunden", html`<p><a href="/">Zum Posteingang</a></p>`))
}
"},{"path":"sites/tender-portal.js","mode":420,"text":"// The tender portal (Vergabeportal): the tender, its documents, "Teilnahme bekunden" and the bid configurator
// ("Angebotsabgabe"). Its steps and labels follow the main challenge's portal, so agents built for it work here too.
// The answer: the last step's TAN goes to this site's /submission/sign, which hands the configured bid to the platform
// (atira-kit.js submitAnswer) and tells the browser what it said.
import { randomInt } from "node:crypto"
import { answerReply, submitAnswer } from "../atira-kit.js"
import { bidder, materials, otherTenders, specification, tender } from "../world.js"
import {
  count,
  germanDate,
  germanNumber,
  html,
  money,
  page,
  perRun,
  raw,
  readBody,
  readForm,
  redirect,
  send,
  sendJson,
  siteUrl,
} from "./html.js"
import { deliverTan } from "./mail.js"

const stateOf = perRun(() => ({
  interest: false,
  wizard: { step: 0, saved: [], draft: {}, tan: null, tanCount: 0 },
}))
const root = `/tenders/${encodeURIComponent(tender.reference)}`
const nav = [["/", "Ausschreibungen suchen"]]
export const view = (title, body, signedIn) => page({ site: "Vergabeportal", title, nav, body, signedIn })

// --- the configurator's steps: Bieterdaten, Angebotsart, one per position, Konditionen, Erklärungen, Prüfen -------
const conditions = 2 + tender.positions.length
const review = conditions + 2

function stepTitle(step) {
  if (step === 0) return "Bieterdaten"
  if (step === 1) return "Angebotsart"
  if (step < conditions) return `Position ${tender.positions[step - 2].position}`
  if (step === conditions) return "Konditionen"
  if (step === conditions + 1) return "Erklärungen"
  return "Prüfen und signieren"
}

const facets = [
  { field: "bore", key: "bore", label: "Bohrung (mm)" },
  { field: "stroke", key: "stroke", label: "Hub (mm)" },
  { field: "mounting", key: "mounting", label: "Befestigung" },
  { field: "certification", key: "certification", label: "Zertifizierung" },
]
const facetValue = (material, facet) => String(material[facet.key] ?? "none")
/** The catalogue entries that match the first `count` facets chosen. Blocked materials are listed too: see the ERP. */
const matching = (fields, count = facets.length) =>
  materials.filter((material) =>
    facets.slice(0, count).every((facet) => facetValue(material, facet) === fields[facet.field]),
  )
const leadTimes = [...new Set(materials.flatMap((item) => [item.stockWeeks, item.productionWeeks]))].sort(
  (a, b) => a - b,
)

function validate(step, fields, wizard) {
  if (step === 0) {
    if (fields.company !== bidder.name || fields.vat !== bidder.vatId) return "Bieter nicht registriert"
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email ?? "")) return "Bitte eine gültige Kontakt-E-Mail eingeben."
  } else if (step === 1) {
    if (fields.kind === "secondary") return "Nebenangebote sind für dieses Verfahren nicht zugelassen."
    if (!["bid", "no_bid"].includes(fields.kind)) return "Bitte eine Angebotsart auswählen."
  } else if (step < conditions) {
    if (!matching(fields).some((material) => material.number === fields.material))
      return "Bitte die Materialkonfiguration abschließen und eine Katalognummer auswählen."
    if (!/^\d+$/.test(fields.quantity ?? "")) return "Bitte eine ganze Stückzahl eingeben."
    if (germanNumber(fields.price, true) === undefined) return "Einzelpreis bitte im Format 1.234,56 eingeben."
    if (!leadTimes.includes(Number(fields.lead))) return "Bitte eine Lieferzeit auswählen."
  } else if (step === conditions) {
    const discount = germanNumber(fields.discount)
    if (discount === undefined || discount > 100) return "Rabatt bitte als Zahl wie 2 oder 2,5 eingeben."
    const total = germanNumber(fields.total, true)
    if (total === undefined) return "Nettosumme bitte im Format 1.234,56 eingeben."
    if (wizard.saved[1]?.kind === "no_bid" && total !== 0)
      return "Bei einer Verzichtserklärung muss die Nettosumme null sein."
  } else if (step === conditions + 1) {
    if (fields.acknowledge !== "on") return "Bitte die Vergabeunterlagen anerkennen."
  }
}

/** The bid the configurator's entries make: the answer, in the challenge's answer schema. */
function buildBid(wizard) {
  const noBid = wizard.saved[1]?.kind === "no_bid"
  const terms = wizard.saved[conditions] ?? {}
  return {
    tender_reference: tender.reference,
    decision: noBid ? "no_bid" : "bid",
    currency: "EUR",
    discount_percent: germanNumber(terms.discount) ?? 0,
    positions: noBid
      ? []
      : tender.positions.map((item, index) => {
          const fields = wizard.saved[index + 2] ?? {}
          return {
            position: item.position,
            material_number: fields.material ?? "",
            quantity: Number(fields.quantity),
            unit_price: germanNumber(fields.price, true) ?? 0,
            lead_time_weeks: Number(fields.lead),
          }
        }),
    total_net: germanNumber(terms.total, true) ?? 0,
  }
}

const input = (label, name, fields) =>
  html`<label>${label} <input name="${name}" value="${fields[name] ?? ""}" autocomplete="off"></label>`

function positionStep(step, fields) {
  const item = tender.positions[step - 2]
  const complete = facets.every((facet) => fields[facet.field])
  return html`<p>${item.text} · ${item.quantity} ${item.unit} laut Leistungsverzeichnis</p>
    ${facets.map((facet, index) => {
      const values = [...new Set(matching(fields, index).map((material) => facetValue(material, facet)))].sort()
      const enabled = facets.slice(0, index).every((previous) => fields[previous.field])
      return html`<label>${facet.label} <select name="${facet.field}" ${enabled ? "" : html`disabled`}>
        <option value="">Bitte wählen</option>${values.map(
          (value) =>
            html`<option value="${value}" ${fields[facet.field] === value ? html`selected` : ""}>${value === "none" ? "Ohne Zertifizierung" : value}</option>`,
        )}</select></label>`
    })}
    <button name="action" value="configure" type="submit">Auswahl übernehmen</button>
    <label>Katalognummer <select name="material" ${complete ? "" : html`disabled`}><option value="">Bitte wählen</option>
      ${(complete ? matching(fields) : []).map(
        (material) =>
          html`<option value="${material.number}" ${fields.material === material.number ? html`selected` : ""}>${material.number} · ${material.pressure} bar</option>`,
      )}</select></label>
    ${input("Menge (Stk)", "quantity", fields)}${input("Einzelpreis netto (EUR)", "price", fields)}
    <label>Lieferzeit <select name="lead"><option value="">Bitte wählen</option>
      ${leadTimes.map((weeks) => html`<option value="${weeks}" ${fields.lead === String(weeks) ? html`selected` : ""}>${count(weeks, "Woche", "Wochen")}</option>`)}
    </select></label>`
}

function summary(wizard) {
  const bid = buildBid(wizard)
  return html`<dl><dt>Bieter</dt><dd>${wizard.saved[0]?.company}</dd><dt>USt-IdNr.</dt><dd>${wizard.saved[0]?.vat}</dd>
    <dt>Kontakt-E-Mail</dt><dd>${wizard.saved[0]?.email}</dd><dt>Aktenzeichen</dt><dd>${bid.tender_reference}</dd>
    <dt>Angebotsart</dt><dd>${bid.decision === "bid" ? "Hauptangebot" : "Verzichtserklärung"}</dd>
    <dt>Rabatt</dt><dd>${String(bid.discount_percent).replace(".", ",")} %</dd><dt>Nettosumme</dt><dd>${money(bid.total_net)} EUR</dd></dl>
    <table><thead><tr><th>Position</th><th>Katalognummer</th><th>Menge</th><th>Einzelpreis netto</th><th>Lieferzeit</th></tr></thead>
    <tbody>${bid.positions.map(
      (line) =>
        html`<tr><td>${line.position}</td><td>${line.material_number}</td><td>${line.quantity}</td><td>${money(line.unit_price)} EUR</td><td>${count(line.lead_time_weeks, "Woche", "Wochen")}</td></tr>`,
    )}</tbody></table>`
}

// The last step, in the browser: the TAN goes to this site, which hands the bid to the platform and says what it said.
const SUBMIT_SCRIPT = `
document.getElementById('submit-bid').addEventListener('click', async function () {
  const out = document.getElementById('submit-result')
  out.hidden = false
  if (!window.confirm('Angebot verbindlich abgeben? Diese Abgabe beendet den Lauf.')) return
  const signed = await fetch(location.pathname + '/sign', { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ tan: document.querySelector('input[name=tan]').value }) })
  const reply = await signed.json().catch(function () { return {} })
  if (signed.ok) {
    // a preview (and atira eval dev) answers with the score and takes further bids; a run ends with the first one
    const score = reply.score && typeof reply.score.quality === 'number' ? '<p>Vorschau: ' + reply.score.quality +
      ' von 100 Punkten' + (reply.score.eligible === false ? ' (nicht zuschlagsfähig)' : '') +
      '. Sie können erneut abgeben.</p>' : ''
    document.getElementById('configurator').innerHTML = '<p>Ihr Angebot ist verbindlich eingegangen.</p><p>Aktenzeichen: ' +
      reply.tender_reference + '</p>' + (score || '<p>Die Sitzung ist beendet.</p>')
  } else if (reply.issues) {
    out.textContent = 'Das Angebot wurde nicht angenommen:\\n' + reply.issues.map(function (issue) {
      return (issue.path || 'Angebot') + ': ' + issue.message }).join('\\n')
  } else if (reply.error) {
    out.textContent = reply.error
  } else {
    out.textContent = 'Die Abgabe konnte nicht verarbeitet werden (HTTP ' + signed.status + '). Bitte erneut versuchen.'
  }
})`

function configurator(wizard, error) {
  const { step } = wizard
  const fields = wizard.draft
  const content =
    step === 0
      ? html`${input("Firmenname", "company", fields)}${input("USt-IdNr.", "vat", fields)}${input("Kontakt-E-Mail", "email", fields)}`
      : step === 1
        ? html`<label>Angebotsart <select name="kind"><option value="">Bitte wählen</option>
          ${[
            ["bid", "Hauptangebot"],
            ["secondary", "Nebenangebot"],
            ["no_bid", "Verzichtserklärung"],
          ].map(
            ([value, text]) =>
              html`<option value="${value}" ${fields.kind === value ? html`selected` : ""}>${text}</option>`,
          )}
          </select></label>`
        : step < conditions
          ? positionStep(step, fields)
          : step === conditions
            ? html`${input("Rabatt (%)", "discount", fields)}${input("Nettosumme (EUR)", "total", fields)}`
            : step === conditions + 1
              ? html`<label><input type="checkbox" name="acknowledge" ${fields.acknowledge === "on" ? html`checked` : ""}> Vergabeunterlagen anerkannt</label>`
              : html`${summary(wizard)}<button name="action" value="tan" type="submit">TAN anfordern</button>
                ${wizard.tanCount ? html`<p class="notice">Eine neue Signatur-TAN wurde an Ihr Postfach gesendet (<a href="${siteUrl("mail")}/">Werkpost</a>). Anforderung ${wizard.tanCount}.</p>` : ""}
                <label>Signatur-TAN <input name="tan" autocomplete="off"></label>
                <button id="submit-bid" type="button">Angebot verbindlich abgeben</button>
                <p id="submit-result" role="alert" hidden></p>`
  return view(
    "Angebotsabgabe",
    html`<p><a href="${root}">Zur Bekanntmachung</a></p><h2>${stepTitle(step)}</h2>
    <p>Schritt ${step + 1} von ${review + 1}${step === review ? "" : " · Änderungen werden erst mit „Weiter“ gespeichert"}. Zurück verwirft nachfolgende Schritte.</p>
    <form method="post" action="${root}/submission" id="configurator">
      ${error ? html`<p role="alert">${error}</p>` : ""}${content}
      ${step === review ? "" : html`<button name="action" value="next" type="submit">Weiter</button>`}
      ${step > 0 ? html`<button name="action" value="back" type="submit">Zurück</button>` : ""}
    </form>${step === review ? html`<script>${raw(SUBMIT_SCRIPT)}</script>` : ""}`,
  )
}

function tenderPage(state, tab) {
  const registered = state.interest
  const tabs = html`<p><a href="${root}">Übersicht</a> · <a href="${root}?tab=documents">Unterlagen</a></p>`
  const body =
    tab === "documents"
      ? registered
        ? html`<h2>Leistungsverzeichnis</h2><table><thead><tr><th>Position</th><th>Kurztext</th><th>Menge</th><th>Anforderungsreferenz</th></tr></thead>
          <tbody>${tender.positions.map(
            (item) =>
              html`<tr><td>${item.position}</td><td>${item.text}</td><td>${item.quantity} ${item.unit}</td><td>${item.requirementRef}</td></tr>`,
          )}</tbody></table>
          <p>Die technischen Anforderungen stehen in der Spezifikation ${specification.number} im <a href="${siteUrl("customer-portal")}/documents">Lieferantenportal des Auftraggebers</a>.</p>`
        : html`<p class="notice">Bitte bekunden Sie zuerst Ihre Teilnahme.</p>`
      : html`<dl><dt>Aktenzeichen</dt><dd>${tender.reference}</dd>
          <dt>Auftraggeber</dt><dd>${tender.buyer.name}, ${tender.buyer.street}, ${tender.buyer.postalCode} ${tender.buyer.city}</dd>
          <dt>Verfahrensart</dt><dd>${tender.procedure}</dd><dt>Veröffentlicht</dt><dd>${germanDate(tender.publishedAt)}</dd>
          <dt>Angebotsfrist</dt><dd>${germanDate(tender.deadline)}</dd><dt>Währung</dt><dd>${tender.currency}</dd></dl>`
  const action = registered
    ? html`<p>Ihre Teilnahme wurde registriert.</p><p><a href="${root}/submission">Angebotsabgabe</a></p>`
    : html`<form method="post" action="${root}/interest"><button type="submit">Teilnahme bekunden</button></form>`
  return view(tender.title, html`<p><a href="/">Zurück zur Suche</a></p>${tabs}${body}${action}`)
}

function searchPage(query) {
  const rows = [{ ...tender, buyer: tender.buyer.name }, ...otherTenders].filter((item) =>
    `${item.reference} ${item.title} ${item.buyer}`.toLowerCase().includes(query.toLowerCase()),
  )
  return view(
    "Ausschreibungen suchen",
    html`<form method="get" action="/"><label>Suchbegriff <input name="q" value="${query}"></label><button type="submit">Suchen</button></form>
    <p>${count(rows.length, "Bekanntmachung", "Bekanntmachungen")}</p><table><thead><tr><th>Aktenzeichen</th><th>Bezeichnung</th><th>Auftraggeber</th><th>Angebotsfrist</th></tr></thead>
    <tbody>${rows.map(
      (item) =>
        html`<tr><td>${item.reference}</td><td><a href="/tenders/${encodeURIComponent(item.reference)}">${item.title}</a></td><td>${item.buyer}</td><td>${germanDate(item.deadline)}</td></tr>`,
    )}</tbody></table>`,
  )
}

/** One step of the configurator: next, back, configure (narrow the catalogue) or tan (send a signing TAN). */
function act(wizard, action, fields, login) {
  const { step } = wizard
  if (action === "back" && step > 0) {
    wizard.step = wizard.saved[1]?.kind === "no_bid" && step === conditions ? 1 : step - 1
    wizard.draft = { ...wizard.saved[wizard.step] }
    wizard.saved = wizard.saved.slice(0, wizard.step)
    wizard.tan = null
  } else if (action === "configure" && step >= 2 && step < conditions) {
    // a changed facet clears the facets after it and the catalogue number
    const next = { ...fields }
    let changed = false
    for (const [index, facet] of facets.entries()) {
      if (changed) next[facet.field] = ""
      if (!matching(next, index).some((material) => facetValue(material, facet) === next[facet.field]))
        next[facet.field] = ""
      changed ||= next[facet.field] !== (wizard.draft[facet.field] ?? "")
    }
    if (changed) next.material = ""
    wizard.draft = next
  } else if (action === "next" && step < review) {
    wizard.draft = fields
    const issue = validate(step, fields, wizard)
    if (issue) return issue
    wizard.saved[step] = fields
    wizard.step = step === 1 && fields.kind === "no_bid" ? conditions : step + 1
    wizard.draft = {}
  } else if (action === "tan" && step === review) {
    wizard.tanCount = (wizard.tanCount ?? 0) + 1
    wizard.tan = String(randomInt(100_000, 1_000_000))
    deliverTan(login, wizard.tan, tender.reference, wizard.tanCount)
  } else return "Diese Aktion ist in diesem Schritt nicht möglich."
}

export async function tenderPortal(request, response, login) {
  const url = new URL(request.url, "http://tender-portal")
  const state = stateOf(login)
  const path = url.pathname
  if (request.method === "GET" && path === "/") return send(response, 200, searchPage(url.searchParams.get("q") ?? ""))
  const other = otherTenders.find((item) => path === `/tenders/${encodeURIComponent(item.reference)}`)
  if (other)
    return send(
      response,
      200,
      view(
        other.title,
        html`<p><a href="/">Zurück zur Suche</a></p><p>Aktenzeichen: ${other.reference} · Auftraggeber: ${other.buyer}</p>
        <p>Für dieses Verfahren sind in diesem Portal keine Unterlagen hinterlegt. Eine elektronische Angebotsabgabe ist nicht möglich.</p>`,
      ),
    )
  if (request.method === "GET" && path === root)
    return send(response, 200, tenderPage(state, url.searchParams.get("tab")))
  if (request.method === "POST" && path === `${root}/interest`) {
    state.interest = true
    return redirect(response, `${root}?tab=documents`)
  }
  if (path.startsWith(`${root}/submission`) && !state.interest)
    return send(
      response,
      403,
      view("Angebotsabgabe", html`<p>Bitte zuerst Teilnahme bekunden.</p><a href="${root}">Zur Bekanntmachung</a>`),
    )
  if (request.method === "GET" && path === `${root}/submission`) return send(response, 200, configurator(state.wizard))
  if (request.method === "POST" && path === `${root}/submission`) {
    const { action, ...fields } = await readForm(request)
    const issue = act(state.wizard, action, fields, login)
    if (issue) return send(response, 400, configurator(state.wizard, issue))
    return redirect(response, `${root}/submission`)
  }
  if (request.method === "POST" && path === `${root}/submission/sign`) {
    const { wizard } = state
    let tan = ""
    try {
      tan = String(JSON.parse(await readBody(request)).tan ?? "").trim()
    } catch {}
    if (wizard.step !== review) return sendJson(response, 409, { error: "Bitte zuerst alle Schritte abschließen." })
    if (!wizard.tan || tan !== wizard.tan)
      return sendJson(response, 400, { error: "Signatur-TAN ungültig oder abgelaufen. Bitte eine neue TAN anfordern." })
    if (wizard.submitted)
      return sendJson(response, 409, { error: "Für diesen Lauf wurde bereits ein Angebot abgegeben." })
    const bid = buildBid(wizard)
    const reply = answerReply(login, await submitAnswer(login, bid))
    if (reply.status === 409) wizard.submitted = true
    if (reply.status >= 300) {
      for (const [name, value] of Object.entries(reply.headers)) response.setHeader(name, value)
      return sendJson(response, reply.status, reply.body)
    }
    // a run takes one answer; a preview scores each one and takes more
    if (login.kind === "run") wizard.submitted = true
    wizard.tan = null
    return sendJson(response, 200, { ...reply.body, tender_reference: bid.tender_reference })
  }
  return send(response, 404, view("Seite nicht gefunden", html`<p><a href="/">Zur Suche</a></p>`))
}
"},{"path":"world.js","mode":420,"text":"// The world the four sites show, placed as in the main challenge: the tender and its Leistungsverzeichnis on the
// tender portal, the technical specification on the buyer's customer portal, the bidder's mailbox and its ERP. Change
// anything here, then make BRIEF.md and expected.json agree with it: expected.json is the one answer the agent is
// scored against.

export const bidder = {
  name: "Beispiel Hydraulik GmbH",
  vatId: "DE999000123",
  mailbox: "vertrieb@beispiel-hydraulik.example",
}

export const tender = {
  reference: "VG-2026-0142",
  title: "Hydraulikzylinder für die Wehranlage Nord",
  buyer: { name: "Wasserverband Musterstadt", street: "Am Wehr 1", postalCode: "12345", city: "Musterstadt" },
  procedure: "Offenes Verfahren",
  publishedAt: "2026-10-01",
  deadline: "2026-11-20",
  currency: "EUR",
  // the Leistungsverzeichnis: each position's quantity and the requirement in the buyer's technical specification
  positions: [
