/** Calls by model, failures by provider and status, and the hosted models' queue waits. */
function callSummary(calls, now) {
  const models = new Map()
  const failures = new Map()
  const waits = new Map()
  for (const call of calls) {
    const failed = callFailed(call)
    if (failed) {
      const statuses = failures.get(call.provider) ?? new Map()
      statuses.set(call.status, (statuses.get(call.status) ?? 0) + 1)
      failures.set(call.provider, statuses)
    }
    if (typeof call.queue_ms === "number")
      waits.set(call.provider, [...(waits.get(call.provider) ?? []), call.queue_ms])
    if (failed && !call.model) continue
    const name = modelName(call)
    const model = models.get(name) ?? { calls: 0, failed: 0, cost: 0, input: 0, cached: 0, output: 0, ms: 0 }
    model.calls++
    if (failed) model.failed++
    model.cost += call.cost_micro_usd
    model.input += call.input_tokens
    model.cached += call.cache_read_tokens
    model.output += call.output_tokens
    model.ms += callEnd(call, now) - call.at
    models.set(name, model)
  }
  const latencies = sorted(calls.filter((call) => call.status !== 0).map((call) => call.latency_ms))
  return {
    count: calls.length,
    failed: calls.filter(callFailed).length,
    cost: calls.reduce((sum, call) => sum + call.cost_micro_usd, 0),
    inCalls: calls.reduce((sum, call) => sum + (callEnd(call, now) - call.at), 0),
    p50: quantile(latencies, 0.5),
    p95: quantile(latencies, 0.95),
    peak: peakConcurrency(calls, now),
    models: [...models.entries()].sort(([, a], [, b]) => b.cost - a.cost || b.calls - a.calls),
    failures: [...failures.entries()],
    waits: [...waits.entries()].map(([provider, values]) => [provider, sorted(values)]),
  }
}

/** "clef: 52 failed (504 timeout)", "qwen: 3 failed (502 upstream unreachable ×2, 429 rate limited)" */
const failureLines = (failures) =>
  failures.map(([provider, statuses]) => {
    const total = [...statuses.values()].reduce((sum, count) => sum + count, 0)
    const parts = [...statuses.entries()]
      .sort(([, a], [, b]) => b - a)
      .map(([status, count]) => `${statusText(status)}${statuses.size > 1 && count > 1 ? ` ×${count}` : ""}`)
    return `${provider}: ${num(total)} failed (${parts.join(", ")})`
  })

const modelLine = ([name, model]) =>
  `${name}: ${counted(model.calls, "call")}${model.failed ? ` (${num(model.failed)} failed)` : ""}, ${usd(model.cost)}, ${num(model.input)} in${model.cached ? ` (${num(model.cached)} cached)` : ""} / ${num(model.output)} out, ${secs(model.ms)} in calls`

const waitLines = (waits) =>
  waits.map(
    ([provider, values]) =>
      `${provider}: p50 ${secs(quantile(values, 0.5))}, p95 ${secs(quantile(values, 0.95))}, ${secs(values.reduce((sum, value) => sum + value, 0))} in all`,
  )

/** One call as a line: [02:10.4 +3.2s wait 0.8s] qwen/qwen3.8-flash-next 200 in 4,210 (cached 3,900) out 312 $0.00071 id=c_812 */
function callLine(call, origin) {
  const t = origin === null ? null : call.at - origin
  const wait = typeof call.queue_ms === "number" ? ` wait ${secs(call.queue_ms)}` : ""
  const latency = call.status === 0 ? "in flight" : `+${secs(call.latency_ms)}`
  const tokens = callFailed(call)
    ? ""
    : ` in ${num(call.input_tokens)}${call.cache_read_tokens ? ` (cached ${num(call.cache_read_tokens)})` : ""} out ${num(call.output_tokens)}`
  return `[${t === null ? "--:--" : runClock(t, true)} ${latency}${wait}] ${modelName(call)} ${statusText(call.status)}${tokens} ${callUsd(call.cost_micro_usd)} id=c_${call.id}`
}

